     1→/**
     2→ * pulse_shape.js — 脉象波形点阵生成器（openvela chart 版）
     3→ * 原 Zepp OS 版输出 GRADKIENT_POLYLINE 的 {x,y} 点阵；
     4→ * 此版输出 chart line 组件的数值数组（0~100，值越大越靠上），形态参数不变。
     5→ */
     6→var N = 160;         // chart 采样点数（密度越高曲线越平滑）
     7→var TOP = 96, BOT = 4;
     8→
     9→function clamp(v) { return Math.max(BOT, Math.min(TOP, v)); }
    10→
    11→// centerY/amp 以 0~100 值域表示（50 为中轴）
    12→function sinWave(cycles, amp, centerY) {
    13→  var pts = [];
    14→  for (var i = 0; i <= N; i++) {
    15→    pts.push(Math.round(clamp(centerY + amp * Math.sin((i / N) * 2 * Math.PI * cycles))));
    16→  }
    17→  return pts;
    18→}
    19→
    20→function triWave(cycles, amp, centerY) {
    21→  var pts = [];
    22→  var per = N / cycles;
    23→  for (var i = 0; i <= N; i++) {
    24→    var phase = (i % per) / per;
    25→    var t = phase < 0.5 ? phase * 2 : (1 - phase) * 2;
    26→    pts.push(Math.round(clamp(centerY + amp * (t * 2 - 1))));
    27→  }
    28→  return pts;
    29→}
    30→
    31→function jitterWave(cycles, amp, centerY, jitterAmp) {
    32→  var pts = [];
    33→  for (var i = 0; i <= N; i++) {
    34→    var j = (Math.sin(i * 7.3) + Math.sin(i * 13.7)) * jitterAmp;
    35→    pts.push(Math.round(clamp(centerY + amp * Math.sin((i / N) * 2 * Math.PI * cycles) + j)));
    36→  }
    37→  return pts;
    38→}
    39→
    40→function gapWave(cycles, amp, centerY, gapFracs) {
    41→  var pts = [];
    42→  for (var i = 0; i <= N; i++) {
    43→    var gap = gapFracs.some(function (g) { return Math.abs(i - g * N) <= N / 20; });
    44→    pts.push(gap ? Math.round(centerY) : Math.round(clamp(centerY + amp * Math.sin((i / N) * 2 * Math.PI * cycles))));
    45→  }
    46→  return pts;
    47→}
    48→
    49→export function getPulseShape(pulseType) {
    50→  var shapes = {
    51→    fu:   sinWave(4,   45 * 0.9, 42),          // 浮：位浅（偏上），幅大
    52→    chen: sinWave(3.5, 28, 72),                // 沉：位深（偏下）
    53→    chi:  sinWave(2.5, 42, 50),                // 迟：周期少
    54→    shuo: sinWave(7,   38, 50),                // 数：周期密
    55→    hua:  sinWave(4.5, 44, 50),                // 滑：流利圆滑
    56→    se:   jitterWave(3, 30, 55, 14),           // 涩：抖动艰涩
    57→    xu:   sinWave(4,   14, 58),                // 虚：幅小无力
    58→    shi:  triWave(4,   46, 50),                // 实：锐利有力
    59→    xian: triWave(5,   47, 50),                // 弦：绷急如弦
    60→    xi:   sinWave(5,   9,  50),                // 细：如线
    61→    hong: sinWave(3,   48, 50),                // 洪：宽大
    62→    huan: sinWave(4,   38, 50),                // 缓：从容和缓
    63→    jie:  gapWave(4,   38, 50, [0.25, 0.55, 0.85]),        // 结：不定歇止
    64→    dai:  gapWave(4,   38, 50, [0, 0.25, 0.5, 0.75, 1]),   // 代：定数歇止
    65→    flat: sinWave(1,   0,  50),                // 无数据：平线
    66→  };
    67→  return shapes[pulseType] || shapes.huan;
    68→}
