     1→/**
     2→ * HRV 数据存储管理器
     3→ * 按日期分离存储当天和历史数据，优化读写性能
     4→ */
     5→
     6→import { Storage } from './storage';
     7→
     8→const TODAY_FILE = 'hrv_today.json';
     9→const HISTORY_PREFIX = 'hrv_history_';
    10→const HISTORY_INDEX_FILE = 'hrv_history_index.json';
    11→// 历史保留天数：Vela 官方文档要求小内存设备及时清理无用文件
    12→const MAX_HISTORY_DAYS = 14;
    13→
    14→export class HrvStorageManager {
    15→  constructor() {
    16→    this.todayCache = null;
    17→    this.todayDate = null;
    18→    this.historyIndex = null;
    19→  }
    20→
    21→  /**
    22→   * 获取今日数据文件的键名
    23→   */
    24→  _getTodayKey() {
    25→    const now = new Date();
    26→    return `${now.getFullYear()}-${('0' + (now.getMonth() + 1)).slice(-2)}-${('0' + now.getDate()).slice(-2)}`;
    27→  }
    28→
    29→  /**
    30→   * 获取历史数据文件名
    31→   */
    32→  _getHistoryFileKey(dateStr) {
    33→    return `${HISTORY_PREFIX}${dateStr}.json`;
    34→  }
    35→
    36→  /**
    37→   * 初始化存储管理器
    38→   */
    39→  init(callback) {
    40→    // 检查是否需要将旧数据归档
    41→    this._checkAndArchiveOldData(() => {
    42→      // 加载今日数据到缓存
    43→      this._loadTodayData(() => {
    44→        // 加载历史索引
    45→        this._loadHistoryIndex(() => {
    46→          // 清理超期历史文件（保留最近 MAX_HISTORY_DAYS 天）
    47→          this._pruneHistory(() => {
    48→            callback();
    49→          });
    50→        });
    51→      });
    52→    });
    53→  }
    54→
    55→  /**
    56→   * 历史保留策略：索引超出 MAX_HISTORY_DAYS 时删除最旧的历史文件与索引项
    57→   */
    58→  _pruneHistory(callback) {
    59→    const idx = this.historyIndex || [];
    60→    if (idx.length <= MAX_HISTORY_DAYS) {
    61→      callback();
    62→      return;
    63→    }
    64→    const sorted = idx.slice().sort(); // YYYY-MM-DD 字典序即时间序
    65→    const keep = sorted.slice(-MAX_HISTORY_DAYS);
    66→    const drop = sorted.slice(0, sorted.length - MAX_HISTORY_DAYS);
    67→    drop.forEach((dateStr) => {
    68→      Storage.remove(this._getHistoryFileKey(dateStr));
    69→    });
    70→    this.historyIndex = keep;
    71→    Storage.set(HISTORY_INDEX_FILE, keep, () => {
    72→      callback();
    73→    });
    74→  }
    75→
    76→  /**
    77→   * 检查并归档旧数据。根据首条记录的时间戳判断数据真实日期，
    78→   * 而非依赖缓存的 todayDate（首次加载时为 null，会导致误判）。
    79→   */
    80→  _checkAndArchiveOldData(callback) {
    81→    Storage.get(TODAY_FILE, (err, todayData) => {
    82→      if (!todayData || !Array.isArray(todayData) || todayData.length === 0) {
    83→        callback();
    84→        return;
    85→      }
    86→
    87→      const todayStr = this._getTodayKey();
    88→
    89→      // 根据首条记录的时间戳判断数据真实日期
    90→      let dataDate = todayStr;
    91→      if (todayData[0] && todayData[0].timestamp) {
    92→        const d = new Date(todayData[0].timestamp);
    93→        dataDate = `${d.getFullYear()}-${('0' + (d.getMonth() + 1)).slice(-2)}-${('0' + d.getDate()).slice(-2)}`;
    94→      }
    95→
    96→      // 数据是今天的，保持不动
    97→      if (dataDate === todayStr) {
    98→        this.todayDate = todayStr;
    99→        callback();
   100→        return;
   101→      }
   102→
   103→      // 数据是旧日期的，归档到对应日期的历史文件
   104→      const historyFile = this._getHistoryFileKey(dataDate);
   105→      Storage.set(historyFile, todayData, () => {
   106→        this._addToHistoryIndex(dataDate, () => {
   107→          Storage.set(TODAY_FILE, [], () => {
   108→            this.todayCache = null;
   109→            this.todayDate = todayStr;
   110→            callback();
   111→          });
   112→        });
   113→      });
   114→    });
   115→  }
   116→
   117→  /**
   118→   * 加载今日数据到缓存
   119→   */
   120→  _loadTodayData(callback) {
   121→    const todayStr = this._getTodayKey();
   122→
   123→    if (this.todayDate === todayStr && this.todayCache) {
   124→      // 缓存命中
   125→      callback();
   126→      return;
   127→    }
   128→
   129→    Storage.get(TODAY_FILE, (err, data) => {
   130→      this.todayCache = data || [];
   131→      this.todayDate = todayStr;
   132→      callback();
   133→    });
   134→  }
   135→
   136→  /**
   137→   * 加载历史索引
   138→   */
   139→  _loadHistoryIndex(callback) {
   140→    Storage.get(HISTORY_INDEX_FILE, (err, index) => {
   141→      this.historyIndex = index || [];
   142→      callback();
   143→    });
   144→  }
   145→
   146→  /**
   147→   * 添加到历史索引
   148→   */
   149→  _addToHistoryIndex(dateStr, callback) {
   150→    Storage.get(HISTORY_INDEX_FILE, (err, index) => {
   151→      let historyIndex = index || [];
   152→      if (historyIndex.indexOf(dateStr) === -1) {
   153→        historyIndex.push(dateStr);
   154→        Storage.set(HISTORY_INDEX_FILE, historyIndex, () => {
   155→          if (callback) callback();
   156→        });
   157→      } else {
   158→        if (callback) callback();
   159→      }
   160→    });
   161→  }
   162→
   163→  /**
   164→   * 添加一条 HRV 记录（总是添加到今日数据）
   165→   */
   166→  addRecord(record, callback) {
   167→    this._loadTodayData(() => {
   168→      if (!this.todayCache) {
   169→        this.todayCache = [];
   170→      }
   171→
   172→      this.todayCache.push(record);
   173→
   174→      // 保存到今日文件
   175→      Storage.set(TODAY_FILE, this.todayCache, () => {
   176→        if (callback) callback();
   177→      });
   178→    });
   179→  }
   180→
   181→  /**
   182→   * 获取今日所有数据
   183→   */
   184→  getTodayData(callback) {
   185→    this._loadTodayData(() => {
   186→      callback(this.todayCache || []);
   187→    });
   188→  }
   189→
   190→  /**
   191→   * 获取指定日期的历史数据
   192→   */
   193→  getHistoryData(dateStr, callback) {
   194→    const historyFile = this._getHistoryFileKey(dateStr);
   195→    Storage.get(historyFile, (err, data) => {
   196→      callback(data || []);
   197→    });
   198→  }
   199→
   200→  /**
   201→   * 获取所有历史日期索引
   202→   */
   203→  getHistoryIndex(callback) {
   204→    this._loadHistoryIndex(() => {
   205→      callback(this.historyIndex || []);
   206→    });
   207→  }
   208→
   209→  /**
   210→   * 获取最近 N 天的数据（跨文件查询）
   211→   */
   212→  getRecentDays(days, callback) {
   213→    const result = [];
   214→
   215→    // 先获取今日数据
   216→    this.getTodayData((todayData) => {
   217→      result.push(...todayData);
   218→
   219→      // 如果只需要今日数据，直接返回
   220→      if (days === 1) {
   221→        callback(result);
   222→        return;
   223→      }
   224→
   225→      // 从历史索引中获取最近几天的日期
   226→      this.getHistoryIndex((historyIndex) => {
   227→        const sortedHistory = historyIndex.sort((a, b) => new Date(b).getTime() - new Date(a).getTime()); // 按日期降序
   228→        let fetchedDays = 0;
   229→        let historyDataPromises = [];
   230→
   231→        // 异步获取历史数据
   232→        for (let i = 0; i < sortedHistory.length && fetchedDays < days - 1; i++) {
   233→          const dateStr = sortedHistory[i];
   234→          historyDataPromises.push(new Promise(resolve => {
   235→            this.getHistoryData(dateStr, (dayData) => {
   236→              result.push(...dayData);
   237→              fetchedDays++;
   238→              resolve();
   239→            });
   240→          }));
   241→        }
   242→
   243→        // 等待所有历史数据获取完毕
   244→        Promise.all(historyDataPromises).then(() => {
   245→          callback(result);
   246→        });
   247→      });
   248→    });
   249→  }
   250→
   251→  /**
   252→   * 清除所有历史数据（保留今日数据）
   253→   */
   254→  clearHistory(callback) {
   255→    this._loadHistoryIndex(() => {
   256→      if (!this.historyIndex || this.historyIndex.length === 0) {
   257→        if (callback) callback();
   258→        return;
   259→      }
   260→
   261→      let deletedCount = 0;
   262→      this.historyIndex.forEach((dateStr) => {
   263→        const historyFile = this._getHistoryFileKey(dateStr);
   264→        Storage.remove(historyFile); // Storage.remove 是同步的，不需要回调
   265→        deletedCount++;
   266→        if (deletedCount >= this.historyIndex.length) {
   267→          // 清空索引
   268→          Storage.set(HISTORY_INDEX_FILE, [], () => {
   269→            this.historyIndex = [];
   270→            if (callback) callback();
   271→          });
   272→        }
   273→      });
   274→    });
   275→  }
   276→
   277→  /**
   278→   * 清除今日数据
   279→   */
   280→  clearToday(callback) {
   281→    Storage.set(TODAY_FILE, [], () => {
   282→      this.todayCache = [];
   283→      if (callback) callback();
   284→    });
   285→  }
   286→
   287→  /**
   288→   * 获取存储统计信息
   289→   */
   290→  getStats(callback) {
   291→    const stats = {
   292→      todayCount: 0,
   293→      historyDays: 0,
   294→      totalRecords: 0
   295→    };
   296→
   297→    this.getTodayData((todayData) => {
   298→      stats.todayCount = todayData.length;
   299→      stats.totalRecords += todayData.length;
   300→
   301→      this.getHistoryIndex((index) => {
   302→        stats.historyDays = index.length;
   303→
   304→        // 计算历史总记录数（可选，可能需要较长时间）
   305→        let loadedCount = 0;
   306→        if (index.length === 0) {
   307→          callback(stats);
   308→          return;
   309→        }
   310→
   311→        index.forEach((dateStr) => {
   312→          this.getHistoryData(dateStr, (dayData) => {
   313→            stats.totalRecords += dayData.length;
   314→            loadedCount++;
   315→
   316→            if (loadedCount >= index.length) {
   317→              callback(stats);
   318→            }
   319→          });
   320→        });
   321→      });
   322→    });
   323→  }
   324→}
