     1→/**
     2→ * storage.js — JSON 文件存取封装（openvela @system.file 版）
     3→ * 接口与 Zepp OS 版保持一致：set/get/patch/getField/remove（回调式）。
     4→ *
     5→ * 内存写穿缓存：写入先落内存并立即回调（文件异步持久化），
     6→ * 读取内存命中直接返回——既加速又消除"写后立读"的时序竞态。
     7→ */
     8→import file from '@system.file';
     9→
    10→function uriOf(name) {
    11→  return 'internal://files/' + name;
    12→}
    13→
    14→// 内存缓存：fileName → 数据对象（进程生命周期内有效）
    15→const memCache = {};
    16→
    17→export const Storage = {
    18→  /**
    19→   * 写入 JSON 文件；data 为 null 时删除文件。
    20→   * 内存立即生效并回调，文件写入异步进行。
    21→   */
    22→  set(fileName, data, callback) {
    23→    if (data === null) {
    24→      delete memCache[fileName];
    25→      file.delete({ uri: uriOf(fileName), fail: () => {} });
    26→      if (callback) callback(null, true);
    27→      return;
    28→    }
    29→    memCache[fileName] = data;
    30→    if (callback) callback(null, true);
    31→    file.writeText({
    32→      uri: uriOf(fileName),
    33→      text: JSON.stringify(data),
    34→      fail: (d, code) => {
    35→        console.log(`[storage] write ${fileName} fail: ${code}`);
    36→      }
    37→    });
    38→  },
    39→
    40→  /**
    41→   * 读取 JSON 文件；内存命中直接返回，未命中读文件并回填缓存。
    42→   * 不存在/解析失败回调 (null, null)。
    43→   */
    44→  get(fileName, callback) {
    45→    if (fileName in memCache) {
    46→      callback(null, memCache[fileName]);
    47→      return;
    48→    }
    49→    file.readText({
    50→      uri: uriOf(fileName),
    51→      success: (data) => {
    52→        try {
    53→          const parsed = JSON.parse(data.text);
    54→          memCache[fileName] = parsed;
    55→          callback(null, parsed);
    56→        } catch (e) {
    57→          callback(null, null);
    58→        }
    59→      },
    60→      fail: () => { callback(null, null); }
    61→    });
    62→  },
    63→
    64→  /**
    65→   * 合并更新 JSON 对象文件的若干字段。
    66→   */
    67→  patch(fileName, patchData, callback) {
    68→    this.get(fileName, (err, currentData) => {
    69→      const newData = Object.assign({}, currentData || {}, patchData);
    70→      this.set(fileName, newData, callback);
    71→    });
    72→  },
    73→
    74→  /**
    75→   * 读取 JSON 对象文件中的单个字段。
    76→   */
    77→  getField(fileName, field, callback) {
    78→    this.get(fileName, (err, data) => {
    79→      if (data && typeof data === 'object') {
    80→        callback(null, data[field]);
    81→      } else {
    82→        callback(null, null);
    83→      }
    84→    });
    85→  },
    86→
    87→  /**
    88→   * 删除文件（内存与磁盘同步清除，忽略失败）。
    89→   */
    90→  remove(fileName) {
    91→    delete memCache[fileName];
    92→    file.delete({ uri: uriOf(fileName), fail: () => {} });
    93→  }
    94→};
    95→

