   272→export function analyzeTrend(currentSdnn, currentSdann, historyRecords) {
   273→  if (!historyRecords || historyRecords.length < 3) {
   274→    return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   275→  }
   276→  const recent = historyRecords.slice(-7);
   277→  const sdnnValues = recent.map(r => (r.metrics && r.metrics.sdnn) || r.sdnn || 0).filter(v => v > 0);
   278→  if (sdnnValues.length < 3) return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   279→
   280→  const avgSdnn = sdnnValues.reduce((a, b) => a + b, 0) / sdnnValues.length;
   281→  const changeRate = avgSdnn > 0 ? (currentSdnn - avgSdnn) / avgSdnn : 0;
   282→
   283→  let direction = 'stable', labelKey = 'trend_stable';
   284→  if (changeRate > 0.15)      { direction = 'improving'; labelKey = 'trend_improving'; }
   285→  else if (changeRate > 0.05) { direction = 'slightly_improving'; labelKey = 'trend_slightly_improving'; }
   286→  else if (changeRate < -0.15) { direction = 'declining'; labelKey = 'trend_declining'; }
   287→  else if (changeRate < -0.05) { direction = 'slightly_declining'; labelKey = 'trend_slightly_declining'; }
   288→  return { trend: direction, label: getText(labelKey), direction, changeRate: Math.round(changeRate * 100) / 100 };
   289→}
